import {JOURNEY_STATUSES,EVENT_TYPES,EVENT_STATUSES,isOpen,assessed,timeline,milestones,validateEvent,validateACTSReferral,recordChanges} from './journey.mjs?v=2.0.2';
import {SEED,DIRECTORY} from './data.mjs?v=2.0.2';
import {ACTION_STATUSES,REFERRAL_STATUSES,FOLLOW_STATUSES,unresolved,overdue,waiting,followWaiting,uid,fmt,stamp,staffName,counts,filterReferrals,changeActionStatus,nextStep,newReferral,summary,validateReferral,validateFollow,saveState,loadState} from './core.mjs?v=2.0.2';
const app=document.getElementById('app'),dialog=document.getElementById('editor');
let timelineView='summary',timelineFilters={scope:'',type:'',status:'',order:'oldest'};
let state,storageError='',page='overview',referralId=null,tab='journey',actionFilter='',filters={search:'',site:'',ward:'',worker:'',from:'',to:'',status:'',attention:'',journey:'Open'},opener=null,toastTimer;
try{state=loadState(localStorage,SEED)}catch(error){state=structuredClone(SEED);storageError=error.message+' The original data has not been overwritten. Reset the demonstration data to start again.';}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${{
 bridge:'<path d="M3 19h18M4 16V8m16 8V8M4 9c5 8 11 8 16 0M8 13v6m4-4v4m4-6v6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',folder:'<path d="M3 7h7l2 2h9v11H3zM3 7V4h7l2 3h8v2"/>',book:'<path d="M12 5v15M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2z"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m10 3-1 3-3 1-3-1-2 4 3 2v3l-2 2 3 3 3-1 3 1 1 3 4-1 1-3 2-2 3 1 1-4-3-2-1-3 1-2-3-2-3 1z"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3c0-4 16-4 16 0v3"/>',send:'<path d="m3 3 18 9-18 9 3-9zM6 12h15"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-12 5h2m3 0h2"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-4-4L5 15z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',print:'<path d="M6 8V3h12v5M6 17H3V9h18v8h-3M6 14h12v7H6zM17 11h1"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1"/>',building:'<path d="M4 21V5h16v16M9 21v-5h6v5M8 9h1m6 0h1M8 12h1m6 0h1"/>',shield:'<path d="m12 3 8 3v7c0 4-8 8-8 8s-8-4-8-8V6zM8 12l3 3 5-6"/>',refresh:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',heart:'<path d="M12 21 3 12C-2 5 7 0 12 7c5-7 14-2 9 5z"/>'}[name]||'<circle cx="12" cy="12" r="8"/>'}</svg>`;
const btn=(label,action,cls='',attrs='',ic='')=>`<button type="button" class="btn ${cls}" data-act="${action}" ${attrs}>${ic?icon(ic):''}${label}</button>`;
const pill=(status)=>`<span class="pill ${['Completed','Confirmed','Accepted','Resolved','Agreed','Arranged'].includes(status)?'good':['Pending','Preparation','Open','Action agreed','Unassigned'].includes(status)?'warn':['Overdue'].includes(status)?'bad':['Submitted','In progress'].includes(status)?'blue':''}">${esc(status)}</span>`;
const selectOptions=(values,value)=>values.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`}).join('');
const field=(label,name,value='',type='text',extra='',hint='')=>`<div class="field ${extra.includes('data-full')?'full':''}"><label for="${name}">${label}</label>${type==='textarea'?`<textarea id="${name}" name="${name}" ${extra}>${esc(value)}</textarea>`:`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}${hint?`<div class="hint">${hint}</div>`:''}</div>`;
const select=(label,name,value,options,extra='')=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}" ${extra}>${selectOptions(options,value)}</select></div>`;
const ownerSelect=(name,value,label='Responsible practitioner')=>select(label,name,value,[['','Unassigned'],...state.staff.map(s=>[s.id,s.name])]);
const empty=(title,description,button='')=>`<div class="empty">${icon('folder')}<h3>${title}</h3><p>${description}</p>${button}</div>`;
const notice=(title,text,warning=false)=>`<div class="notice ${warning?'warning':''}">${icon('info')}<div><h3>${title}</h3><p>${text}</p></div></div>`;
const current=()=>state.referrals.find(e=>e.id===referralId);
const person=()=>state.staff.find(s=>s.id===state.selectedStaff)||state.staff[0];
function flash(message){const el=document.getElementById('feedback');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),5000);}
function persist(next,message='Changes saved in this browser.',reset=false){
 if(storageError&&!reset){flash('Saved data could not be read. Reset the demonstration dataset before saving new changes.');return false;}
 try{saveState(localStorage,next);state=next;storageError='';if(message)flash(message);return true;}catch(err){flash('Save failed. Your previous saved data is unchanged. Check browser storage availability.');return false;}
}
function updateReferral(mutator,message){const next=structuredClone(state),e=next.referrals.find(e=>e.id===referralId);const before=structuredClone(e);mutator(e);recordChanges(before,e,state.selectedStaff);e.updatedAt=new Date().toISOString();return persist(next,message);}
function navigate(next,id=null,newTab='journey'){if(!safeLeave())return;page=next;referralId=id;tab=newTab;actionFilter='';timelineView='summary';timelineFilters={scope:'',type:'',status:'',order:'oldest'};render(true);}
function safeLeave(){const el=document.getElementById('summary-content');if(el&&el.value!==el.dataset.initial){return confirm('Leave without saving your edited handover draft?');}return true;}
function render(focus=false){const previous=document.activeElement,p=person();app.innerHTML=`<div class="shell"><aside class="sidebar" aria-label="Application navigation"><div class="brand"><span class="brand-mark">${icon('bridge')}</span><div><strong>Recovery Bridge</strong><small>ACTS REFERRAL JOURNEYS</small></div></div><div class="nav-label">YOUR WORKSPACE</div><nav>${nav('Referral register','overview','grid')}${nav('Service directory','directory','building')}</nav><div class="nav-label">PROTOTYPE RESOURCES</div><nav>${nav('Guide & research','guide','book')}${nav('Demo settings','settings','settings')}</nav><div class="sidebar-bottom"><div class="prototype-card"><strong>Research prototype</strong>Fictional scenarios only.<br>Do not enter patient information.</div><div class="sidebar-foot">Designed around what matters.<br>Built for a connected handover.</div></div></aside><div class="content"><header class="topbar"><div class="breadcrumb">Inpatient alcohol care ${icon('chevron')} <span>${page==='referral'?'ACTS referral workspace':({overview:'Referral register',directory:'Service directory',guide:'Guide & research',settings:'Demo settings'}[page])}</span></div><div class="profile"><span class="avatar" aria-hidden="true">${esc(p.initials)}</span><div><label for="demo-staff">Demonstration view</label><select id="demo-staff">${selectOptions(state.staff.map(s=>[s.id,s.name+' · '+(s.id==='omar'?'Coordinator':s.id==='ellis'?'Team lead':'Practitioner')]),p.id)}</select></div></div></header><div class="demo-strip"><span>${icon('shield')} <strong>Synthetic data only</strong> · Research prototype</span><span>Demo date: <strong>${fmt(state.today)}</strong> · Saved on this device</span></div><main id="main" tabindex="-1">${state.migrationNotice?notice('Saved plans retained',esc(state.migrationNotice)):''}${storageError?notice('Saved data needs attention',esc(storageError),true):''}${page==='overview'?overview():page==='referral'?workspace():page==='directory'?directory():page==='settings'?settings():guide()}<footer class="footer-note"><span>Recovery and discharge coordination · Staff retain responsibility for clinical decisions.</span><span>Prototype v2.0 · All people and services are fictional</span></footer></main></div></div>`;
 if(focus)document.querySelector('main h1')?.focus();else focusMatch(previous);
}
function focusMatch(previous){if(!previous)return false;let replacement=previous.id?document.getElementById(previous.id):null;const d=previous.dataset;if(!replacement&&d?.act){let selector=`[data-act="${CSS.escape(d.act)}"]`;for(const key of ['id','tab','key','page','view'])if(d[key])selector+=`[data-${key}="${CSS.escape(d[key])}"]`;replacement=app.querySelector(selector);if(!replacement&&['complete-action','reopen-action'].includes(d.act)){const next=d.act==='complete-action'?'reopen-action':'complete-action';replacement=app.querySelector(`[data-act="${next}"][data-id="${CSS.escape(d.id)}"]`);}}if(replacement){replacement.focus();return true;}return false;}
function nav(label,p,ic){return `<button type="button" class="nav-btn ${page===p||(p==='overview'&&page==='referral')?'active':''}" data-act="nav" data-page="${p}" ${page===p?'aria-current="page"':''}>${icon(ic)}${label}${p==='overview'?`<span class="nav-count">${state.referrals.filter(isOpen).length}</span>`:''}</button>`;}
function overview(){const es=filterReferrals(state.referrals,filters,state.today),n=counts(es,state.today);const metrics=[['referrals','ACTS referrals','folder','Matching your filters',''],['assessment','Assessment to record','user','Open, no completed assessment','amber'],['outstanding','Outstanding actions','list','Includes not recorded',''],['overdue','Overdue actions','clock','Due before the demo date','red'],['unassigned','Unassigned actions','user','Outstanding, without an owner','amber'],['responses','Onward response pending','send','Submitted onward referrals','amber'],['followups','Follow-up to confirm','calendar','Pending or not recorded','amber']];
return `<div class="page-head"><div><div class="eyebrow">ADDICTIONS TEAM · ACTS</div><h1 tabindex="-1">ACTS referral register</h1><p>Follow each person’s journey from referral through treatment and follow-up.</p></div>${btn('New ACTS referral','new-acts-referral','primary','','plus')}</div><div class="stats">${metrics.map(([key,label,ic,detail,color])=>`<button type="button" class="stat ${color} ${filters.attention===key?'selected':''}" data-act="metric" data-key="${key}" aria-pressed="${filters.attention===key}"><div class="stat-top">${label}<span class="stat-icon">${icon(ic)}</span></div><strong>${n[key]}</strong><small>${detail}</small></button>`).join('')}</div><p class="scope">Counts reflect <strong>${es.length}</strong> ACTS referrals matching the current filters (${n.open} open). Actions and onward arrangements are counted individually.</p><section class="panel filter-panel" aria-label="ACTS referral filters"><div class="search-line"><div class="searchbox"><label class="hidden" for="search">Search ACTS referrals</label>${icon('search')}<input id="search" aria-label="Search ACTS referrals" placeholder="Search by referral, fictional name, goal or event…" value="${esc(filters.search)}" data-filter="search"></div>${btn('My referrals','my-referrals','','','user')}${btn('Clear filters','clear-filters','ghost')}</div><div class="filters">${select('Journey status','filter-journey',filters.journey||'Open',[['Open','All open journeys'],['All','All journeys'],...JOURNEY_STATUSES],'data-filter="journey"')}${select('Site','filter-site',filters.site,[['','All sites'],'Poole','Bournemouth'],'data-filter="site"')}${select('Ward','filter-ward',filters.ward,[['','All wards'],...new Set(state.referrals.map(e=>e.ward).filter(Boolean))],'data-filter="ward"')}${select('Assigned worker','filter-worker',filters.worker,[['','All staff'],...state.staff.map(s=>[s.id,s.name])],'data-filter="worker"')}${field('Planned discharge from','filter-from',filters.from,'date','data-filter="from"')}${field('Planned discharge to','filter-to',filters.to,'date','data-filter="to"')}${select('Action status','filter-status',filters.status,[['','All statuses'],...ACTION_STATUSES],'data-filter="status"')}</div>${filters.from&&filters.to&&filters.from>filters.to?'<p class="form-error" role="alert">The end date is earlier than the start date. Adjust the date range.</p>':''}</section>${rolePanel(es)}<section class="panel" aria-labelledby="referrals-heading"><div class="panel-head"><div><h2 id="referrals-heading">Referrals & treatment journeys <span class="muted small">${es.length} of ${state.referrals.length}</span></h2><p>Closed journeys remain available through the journey status filter.</p></div><span class="save-state">${icon('check')} Changes persist on refresh</span></div>${es.length?`<div class="table-wrap"><table><thead><tr><th scope="col">Person / ACTS referral</th><th scope="col">Received & practitioner</th><th scope="col">Journey / planned discharge</th><th scope="col">Latest recorded event</th><th scope="col">Needs attention</th><th scope="col">Open</th></tr></thead><tbody>${es.map(referralRow).join('')}</tbody></table></div>`:empty('No referrals match these filters','Try another status, worker or date range. Missing dates do not match a date range.',btn('Clear filters','clear-filters'))}<div class="legend">${pill('Not recorded')} ${pill('Planned')} ${pill('Completed')} ${pill('Declined')} ${pill('Not applicable')}</div></section><section class="panel"><div class="panel-head"><div><h2>Next useful steps</h2><p>Review the next contact, ownership and outstanding coordination work.</p></div></div>${es.slice(0,3).map(e=>{const next=nextStep(e,state.today);return `<div class="attention-item"><span class="small-icon">${icon('arrow')}</span><div><strong>${esc(e.alias)} · ${next.title}</strong><p>${esc(next.detail)}</p></div>${btn('Review','open','','data-id="'+esc(e.id)+'" data-tab="'+next.tab+'"')}</div>`}).join('')||empty('Nothing to show','Clear a filter to see the next steps.')}</section>`;}

function referralRow(e){const n=counts([e],state.today),latest=timeline(e,{scope:'treatment',order:'newest'}).find(v=>v.date&&v.status==='Completed'&&v.date<=state.today);return `<tr><td><button type="button" class="episode-link" data-act="open" data-id="${esc(e.id)}"><span class="episode-avatar" aria-hidden="true">${esc(e.alias.slice(0,1))}</span><span><strong>${esc(e.alias)}</strong><small>${esc(e.id)}</small></span></button></td><td><strong>${fmt(e.receivedDate)}</strong><br><span class="muted">${esc(staffName(e.practitioner,state.staff))}</span></td><td>${pill(e.journeyStatus)}${e.discharge?`<br><span class="muted">Planned discharge: ${fmt(e.discharge)}</span>`:''}</td><td>${latest?`<strong>${esc(latest.title)}</strong><br><span class="muted">${fmt(latest.date)}</span>`:pill('Not recorded')}<br><span class="muted">${e.events.length} treatment events · ${n.outstanding} outstanding actions</span></td><td><div class="pills">${n.assessment?pill('Assessment not recorded'):''}${n.overdue?`<span class="pill bad">${n.overdue} overdue</span>`:''}${n.unassigned?`<span class="pill warn">${n.unassigned} unassigned</span>`:''}${n.responses?`<span class="pill warn">${n.responses} onward response</span>`:''}${n.followups?`<span class="pill warn">${n.followups} follow-up</span>`:''}${!e.goals.length?pill('Goals not recorded'):''}${!n.outstanding&&!n.responses&&!n.followups?pill('Review plan'):''}</div></td><td>${btn('Open','open','compact',`data-id="${esc(e.id)}" aria-label="Open ACTS referral ${esc(e.id)} for ${esc(e.alias)}"`,'chevron')}</td></tr>`;}

function rolePanel(es){if(person().id==='ellis')return `<section class="panel"><div class="panel-head"><div><h2>Team lead view · work allocation</h2><p>Action ownership across the filtered ACTS referrals. Demonstration view only.</p></div></div><div class="table-wrap"><table class="mini-table"><thead><tr><th scope="col">Owner</th><th scope="col">Outstanding</th><th scope="col">Overdue</th></tr></thead><tbody>${[...state.staff,{id:'',name:'Unassigned'}].map(s=>{const as=es.flatMap(e=>e.actions).filter(a=>a.owner===s.id&&unresolved(a));return `<tr><td>${esc(s.name)}</td><td>${as.length}</td><td>${as.filter(a=>overdue(a,state.today)).length}</td></tr>`}).join('')}</tbody></table></div></section>`;if(person().id==='omar')return notice('Discharge coordinator view','Referrals are ordered by planned discharge date. Review unassigned work and follow-up arrangements together. This demonstration view is not authentication.');return '';}
function workspace(){const e=current();if(!e)return empty('ACTS referral not found','Return to the referral register.',btn('Referral register','nav','','data-page="overview"'));const n=counts([e],state.today),next=nextStep(e,state.today);return `<button type="button" class="back" data-act="nav" data-page="overview">${icon('back')} ACTS referral register</button><div class="episode-head"><div class="episode-title"><span class="episode-avatar" aria-hidden="true">${esc(e.alias.slice(0,1))}</span><div><div class="eyebrow">${esc(e.id)} · FICTIONAL ACTS REFERRAL</div><h1 tabindex="-1">${esc(e.alias)}’s ACTS journey</h1><span class="muted small">${esc(e.scenario||'New fictional scenario')}</span></div></div><div class="button-row">${btn('Edit referral','edit-acts-referral','','','edit')}${btn('Handover preview','tab','primary','data-tab="handover"','folder')}</div></div><div class="episode-meta"><div class="meta-item"><small>Referral received</small><strong>${fmt(e.receivedDate)} ${esc(e.receivedTime)}</strong></div><div class="meta-item"><small>Journey status</small>${pill(e.journeyStatus)}</div><div class="meta-item"><small>Assigned practitioner</small><strong>${esc(staffName(e.practitioner,state.staff))}</strong></div><div class="meta-item"><small>Coordination actions</small><strong>${n.outstanding} outstanding · ${n.overdue} overdue</strong></div></div><div class="referral-context"><p><strong>Referral route:</strong> ${esc(e.route||'Not recorded')}</p><p><strong>Reason for referral:</strong> ${esc(e.reasonForReferral||'Not recorded')}</p><p class="muted small">Last saved: ${stamp(e.updatedAt)} · London time</p></div><div class="next-step">${icon('arrow')}<div><strong>${next.title}</strong><p>${esc(next.detail)}</p><p>${next.why}</p></div>${btn('Review','tab','','data-tab="'+next.tab+'"','chevron')}</div><div class="tabs" role="tablist" aria-label="ACTS referral sections">${[['journey','Treatment journey',e.events.length],['recovery','Recovery support',e.goals.length],['actions','Discharge actions',n.outstanding],['referrals','Onward support',e.onwardReferrals.length],['handover','Handover','']].map(([key,label,c])=>`<button type="button" id="tab-${key}" class="tab ${tab===key?'active':''}" data-act="tab" data-tab="${key}" role="tab" aria-selected="${tab===key}" aria-controls="workspace-panel" tabindex="${tab===key?'0':'-1'}">${label}${c!==''?`<span class="tab-count">${c}</span>`:''}</button>`).join('')}</div><div id="workspace-panel" role="tabpanel" aria-labelledby="tab-${tab}" tabindex="0">${tab==='journey'?journey(e):tab==='recovery'?recovery(e):tab==='actions'?actions(e):tab==='referrals'?referrals(e):handover(e)}</div>${notice('Recorded journey, clinical responsibility','Events describe what staff have recorded. A completed event or checklist does not demonstrate clinical fitness for discharge.')}`;}
function journey(e){const list=timeline(e,timelineFilters);return `<div class="milestones" aria-label="Recorded journey milestones">${milestones(e).map(m=>`<section><small>${m.label}</small><strong>${m.status}</strong><span>${fmt(m.date)}</span></section>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>Treatment journey timeline</h2><p>Referral, contacts, assessments, treatment, discharge and follow-up in one place.</p></div>${btn('Add treatment event','event','primary','','plus')}</div><div class="timeline-toolbar"><div class="view-switch" role="group" aria-label="Timeline view">${['summary','detailed'].map(v=>`<button type="button" class="btn ${timelineView===v?'primary':''}" data-act="timeline-view" data-view="${v}" aria-pressed="${timelineView===v}">${v==='summary'?'Summary view':'Detailed view'}</button>`).join('')}</div><div class="timeline-filters">${select('Show','timeline-scope',timelineFilters.scope,[['','All events'],['treatment','Treatment events'],['updates','Record updates']],'data-timeline="scope"')}${select('Event type','timeline-type',timelineFilters.type,[['','All types'],'Referral received',...EVENT_TYPES,'Record update'],'data-timeline="type"')}${select('Event status','timeline-status',timelineFilters.status,[['','All statuses'],...EVENT_STATUSES,'Recorded'],'data-timeline="status"')}${select('Order','timeline-order',timelineFilters.order,[['oldest','Earliest first'],['newest','Latest first']],'data-timeline="order"')}</div><p class="muted small">${list.length} events shown. Treatment dates are entered by staff. Record updates show when a plan was saved; they are not treatment contacts.</p></div>${!e.events.length?notice('Treatment history not recorded','Add known ACTS contacts and events. Missing history is not treated as completed.'):''}${list.length?`<ol class="journey-timeline ${timelineView}">${list.map(v=>timelineItem(v,e)).join('')}</ol>`:empty('No events match these filters','Choose another event type or status.')}<div class="block small muted">Planned contacts remain planned until staff record their outcome. Milestones summarise recorded events; they do not assess recovery or readiness for discharge.</div></section>`;}
function timelineItem(v,e){const update=v.source==='Record update',receipt=v.id==='receipt',late=v.status==='Planned'&&v.date<state.today;return `<li class="timeline-item ${update?'record-update':''}"><div class="timeline-date">${v.date?`<time datetime="${esc(v.date)}">${fmt(v.date)}</time>`:'Date not recorded'}<small>${update?'Saved '+stamp(v.recordedAt):v.time?esc(v.time):'Time not recorded'}</small></div><div class="timeline-card"><div class="record-title"><div><span class="timeline-source">${esc(v.source)} · ${esc(v.type)}</span><h3>${esc(v.title)}</h3></div>${receipt?btn('Edit referral','edit-acts-referral','compact','','edit'):!update?btn('Edit event','event','compact',`data-id="${esc(v.id)}" aria-label="Edit ${esc(v.title)} on ${fmt(v.date)}"`,'edit'):''}</div><div class="pills">${pill(v.status)}${late?pill('Planned date passed'):''}<span class="muted small">${update?'Recorded by demonstration account:':'Responsible practitioner:'} ${esc(staffName(v.owner,state.staff))}</span></div>${timelineView==='summary'?`<p>${esc(v.outcome||v.notes||'Context not recorded')}</p>${v.nextAction?`<p><strong>Next:</strong> ${esc(v.nextAction)}</p>`:''}`:`<dl class="event-detail">${[['Contact method',v.method],['Location',v.location],['Contact duration',v.duration!==''&&v.duration!=null?v.duration+' minutes':''],['AUDIT score (recorded)',v.auditScore],['Notes / context',v.notes],['Outcome',v.outcome],['Next action',v.nextAction],['Recorded at',v.recordedAt?stamp(v.recordedAt):''],['Last edited',v.updatedAt?stamp(v.updatedAt):'']].filter(([k])=>!update||['Notes / context','Recorded at'].includes(k)).map(([k,value])=>`<div><dt>${k}</dt><dd>${esc(value===0?'0':value||'Not recorded')}</dd></div>`).join('')}</dl>`}</div></li>`;}

function recovery(e){return `<div class="workspace-grid"><div><section class="panel"><div class="panel-head"><div><h2>What matters to ${esc(e.alias)}?</h2><p>Recovery goals expressed by the person.</p></div>${btn('Add goal','goal','compact','','plus')}</div>${e.goals.length?e.goals.map(g=>`<div class="block"><div class="record-title"><div class="quote">${esc(g.text)}<small>Goal recorded in the person’s own terms</small></div>${btn('Edit','goal','compact',`data-id="${esc(g.id)}"`,'edit')}</div></div>`).join(''):empty('Recovery goals not recorded','Start with a brief conversation about what the person wants from their recovery.',btn('Record a goal','goal','','','plus'))}</section><section class="panel"><div class="panel-head"><div><h2>Support discussed and agreed</h2><p>Discussion, offer, decision and arrangement are separate.</p></div>${btn('Add support','support','compact','','plus')}</div>${e.supports.length?e.supports.map(s=>`<div class="record-card"><div class="record-title"><h3>${esc(s.option)}</h3>${btn('Edit','support','compact',`data-id="${esc(s.id)}"`,'edit')}</div><div class="support-stages">${[['Discussion',s.discussed==='Completed'?'Discussed':s.discussed],['Offer',s.offered==='Completed'?'Offered':s.offered],['Person’s decision',s.decision],['Arrangement',s.arrangement==='Completed'?'Arranged':s.arrangement]].map(([l,v])=>`<div><small>${l}</small>${pill(v)}</div>`).join('')}</div><p>${esc(s.notes||'Individual context not recorded.')}</p></div>`).join(''):empty('Support discussion not recorded','Record options discussed, what was offered and the person’s decision separately.')}</section></div><div><section class="panel"><div class="panel-head"><h2>Preferences & review</h2>${btn('Edit','recovery-context','compact','','edit')}</div><div class="block"><div class="detail-label">Preferences</div><p class="body-copy">${esc(e.preferences||'Not recorded')}</p></div><div class="block"><div class="detail-label">Information / resources provided</div><p class="body-copy">${esc(e.resources||'Not recorded')}</p></div><div class="block"><div class="detail-label">Planned review</div><p class="body-copy">${fmt(e.review)}</p></div></section><section class="panel"><div class="panel-head"><div><h2>Practical barriers</h2><p>Review: ${esc(e.barrierReview)}</p></div>${btn('Add','barrier','compact','','plus')}</div>${e.barriers.length?e.barriers.map(b=>`<div class="record-card"><div class="record-title"><h3>${esc(b.type)}</h3>${btn('Edit','barrier','compact',`data-id="${esc(b.id)}"`)}</div>${pill(b.status)}<p>${esc(b.context||'Context not recorded.')}</p><p><strong>Agreed action:</strong> ${esc(b.action||'Not recorded')}</p></div>`).join(''):empty(e.barrierReview==='Not recorded'?'Barriers not yet reviewed':e.barrierReview==='Not applicable'?'Barrier section not applicable':'No barriers recorded',e.barrierReview==='Not recorded'?'Record whether relevant practical needs have been reviewed.':'Record individual context only when relevant.',btn('Update review status','recovery-context','compact'))}</section></div></div>`;}
function inpatientContext(e){const known=e.site||e.ward||e.discharge;return `<section class="panel"><div class="panel-head"><div><h2>Inpatient & discharge context</h2><p>Optional details recorded later, when relevant to the plan.</p></div>${btn(known?'Edit context':'Add context','inpatient-context','compact','','edit')}</div>${known?`<div class="episode-meta planning-meta"><div class="meta-item"><small>Site / ward</small><strong>${esc(e.site||'Not recorded')} · ${esc(e.ward||'Not recorded')}</strong></div><div class="meta-item"><small>Planned discharge</small><strong>${fmt(e.discharge)}</strong></div></div>`:'<div class="block muted small">No inpatient or discharge context recorded. Continue planning and add these details if they become relevant.</div>'}</section>`;}
function actions(e){const list=e.actions.filter(a=>!actionFilter||a.status===actionFilter),completed=e.actions.filter(a=>a.status==='Completed').length,resolved=e.actions.filter(a=>['Declined','Not applicable'].includes(a.status)).length;return `${inpatientContext(e)}<div class="actions-toolbar"><div><h2 style="margin:0">Discharge action plan</h2><p class="muted small" style="margin:4px 0 0">${completed} completed · ${resolved} declined / not applicable · ${e.actions.filter(unresolved).length} outstanding</p></div><div class="button-row">${btn('Use example checklist','checklist','','','list')}${btn('Add action','action','primary','','plus')}</div></div><div class="field action-select" style="margin-bottom:17px"><label for="action-filter">Show actions</label><select id="action-filter">${selectOptions([['','All actions'],...ACTION_STATUSES],actionFilter)}</select></div><section class="panel">${list.length?list.map(a=>`<div class="action-card ${a.status==='Completed'?'completed':''}"><div class="action-main"><span class="status-marker ${a.status==='Completed'?'done':''}" aria-hidden="true">${icon(a.status==='Completed'?'check':a.status==='In progress'?'clock':'list')}</span><div><h3>${esc(a.description)}</h3><div class="pills">${pill(a.status)}${overdue(a,state.today)?pill('Overdue'):''}${!a.owner&&unresolved(a)?pill('Unassigned'):''}</div><div class="record-meta"><span>${icon('user')} ${esc(staffName(a.owner,state.staff))}</span><span>Due: <strong>${fmt(a.due)}</strong></span></div>${a.notes?`<p>${esc(a.notes)}</p>`:''}${a.why?`<p class="muted">Why this matters: ${esc(a.why)}</p>`:''}${a.status==='Completed'?`<div class="completion">Completed ${stamp(a.completedAt)} · London time</div>`:''}</div></div><div class="action-aside">${unresolved(a)?btn('Complete','complete-action','compact',`data-id="${esc(a.id)}"`,'check'):a.status==='Completed'?btn('Reopen','reopen-action','compact',`data-id="${esc(a.id)}"`):''}${btn('Edit','action','compact',`data-id="${esc(a.id)}"`,'edit')}</div></div>`).join(''):empty(e.actions.length?'No actions with this status':'Discharge actions not recorded',e.actions.length?'Choose another action status.':'Use the example checklist, select relevant items and assign owners.',btn('Add action','action','','','plus'))}</section>`;}
function referrals(e){return `<div class="workspace-grid"><section class="panel"><div class="panel-head"><div><h2>Onward referrals</h2><p>Submission ≠ acceptance or engagement.</p></div>${btn('Add onward referral','referral','compact','','plus')}</div>${e.onwardReferrals.length?e.onwardReferrals.map(r=>`<div class="record-card"><div class="record-title"><h3>${esc(r.service)}</h3>${btn('Edit','referral','compact',`data-id="${esc(r.id)}"`,'edit')}</div>${pill(r.status)}<p><strong>Purpose:</strong> ${esc(r.purpose||'Not recorded')}</p><div class="record-meta"><span>Consent: ${esc(r.consent)}</span><span>Date: ${fmt(r.date)}</span><span>Owner: ${esc(staffName(r.owner,state.staff))}</span></div><p><strong>Response / outcome:</strong> ${esc(r.outcome||'Not recorded')}</p><p><strong>Next action:</strong> ${esc(r.next||'Not recorded')}</p>${btn('Record follow-up','followup','compact',`data-ref="${esc(r.id)}" style="margin-top:14px"`,'calendar')}</div>`).join(''):empty('No referrals recorded','This does not mean referrals are unnecessary. Record what was agreed, including declined or not applicable decisions.')}</section><section class="panel"><div class="panel-head"><div><h2>Follow-up arrangements</h2><p>Confirm details independently of the referral.</p></div>${btn('Add','followup','compact','','plus')}</div>${e.followups.length?e.followups.map(f=>`<div class="record-card"><div class="record-title"><h3>${esc(f.service)}</h3>${btn('Edit','followup','compact',`data-id="${esc(f.id)}"`,'edit')}</div>${pill(f.status)}<div class="record-meta"><span>${f.status==='Confirmed'?'Confirmed date':'Recorded date'}: <strong>${fmt(f.date)} ${esc(f.time)}</strong></span><span>Method: ${esc(f.method||'Not recorded')}</span></div><p>${esc(f.details||'Details not recorded')}</p><p><strong>Responsible practitioner:</strong> ${esc(staffName(f.owner,state.staff))}</p><p><strong>Next action:</strong> ${esc(f.next||'Not recorded')}</p>${f.onwardReferralId?`<p class="muted">Linked referral: ${esc(e.onwardReferrals.find(r=>r.id===f.onwardReferralId)?.service||'Not recorded')}</p>`:''}</div>`).join(''):empty('Follow-up not recorded','No appointment or contact arrangement has been recorded.')}</section></div>`;}
function handover(e){const generated=summary(e,state.staff),valid=e.handoverDraft!==null&&e.handoverSource===generated,text=valid?e.handoverDraft:generated;return `${e.handoverDraft!==null&&!valid?notice('The record has changed','This preview has been refreshed from the current record. Earlier handover edits are not used.',true):''}<div class="summary-grid"><section class="panel pad"><div class="record-title"><div><h2>Handover preview</h2><p class="muted small">Review and edit before exporting. Missing information is shown explicitly.</p></div></div><label for="summary-content" class="detail-label">Editable handover summary</label><textarea id="summary-content" class="summary-text" data-initial="${esc(text)}">${esc(text)}</textarea><div id="summary-save" class="inline-result" aria-live="polite">${valid?'Edited draft saved '+stamp(e.handoverSavedAt)+'.':'Generated from the current referral record.'}</div></section><aside class="summary-tools"><section class="panel pad"><h3>Review, then share</h3><p>This is a preview. Nothing is sent to a service.</p>${btn('Save edited draft','save-summary','primary','','check')}${btn('Refresh from record','refresh-summary','','','refresh')}${btn('Print / save as PDF','print-summary','','','print')}${btn('Export text file','export-summary','','','download')}<p>Printing and exporting use the text in the preview. An edited draft is separate from the source record.</p></section><section class="panel pad"><h3>Record checks</h3><p>${e.goals.length?'Recovery goals recorded.':'Recovery goals not recorded.'}</p><p>${e.actions.length?e.actions.filter(unresolved).length+' outstanding actions.':'Discharge actions not recorded.'}</p><p>${e.onwardReferrals.filter(waiting).length} referrals awaiting a response.</p><p>${e.followups.filter(f=>f.status==='Confirmed').length} confirmed follow-up arrangements.</p><p>Not recorded, declined and not applicable remain distinct.</p></section></aside></div>`;}
function directory(){return `<div class="page-head"><div><div class="eyebrow">SUPPORT OPTIONS</div><h1 tabindex="-1">Demonstration service directory</h1><p>Example organisations to support fictional planning scenarios.</p></div></div>${notice('Fictional services only','These organisations, routes and descriptions are demonstration content. No referral is sent and no live service connection is made.')}<div class="directory-grid">${DIRECTORY.map(s=>`<section class="panel pad directory-card">${icon('building')}<div class="tag">${esc(s.category)}</div><h2>${esc(s.name)}</h2><p>${esc(s.description)}</p><dl><dt>Example area</dt><dd>${esc(s.area)}</dd><dt>Example referral route</dt><dd>${esc(s.route)}</dd></dl><p>${esc(s.detail)}</p>${btn('Add to an ACTS referral','directory-referral','','data-service="'+esc(s.name)+'"','plus')}</section>`).join('')}</div>`;}
function settings(){return `<div class="page-head"><div><div class="eyebrow">RESEARCH PROTOTYPE</div><h1 tabindex="-1">Demonstration settings</h1><p>Configure reusable checklist items and control the synthetic dataset.</p></div></div><div class="settings-grid"><section class="panel pad"><h2>Example checklist</h2><p>These are planning prompts, not clinical requirements. Select only relevant items when applying the checklist. Changes affect future applications.</p><form id="templates-form">${state.templates.map((t,i)=>`<div class="template-entry">${field('Action '+(i+1),'template-'+i,t.description,'text','required maxlength="220"')}${field('Why it matters','why-'+i,t.why,'text','maxlength="220"')}</div>`).join('')}<div class="button-row" style="margin-top:15px"><button class="btn primary" type="submit">Save checklist</button>${btn('Add checklist item','add-template','','','plus')}</div><p id="template-error" class="form-error" role="alert"></p></form></section><div><section class="panel pad"><h2>Reference date</h2><p>Overdue actions use this demonstration date, so the scenarios stay consistent for evaluation.</p><form id="date-form">${field('Demonstration date','demo-date',state.today,'date','required')}<button type="submit" class="btn primary" style="margin-top:15px">Update date</button></form></section><section class="panel pad"><h2>Your demonstration data</h2><p>Records are saved in this browser only. Clearing browser storage removes local changes. There is no shared team database.</p>${btn('Export synthetic dataset','export-data','','','download')}<hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><h3>Reset the scenarios</h3><p>Restore the original six scenarios, checklist and reference date. This removes local edits.</p>${btn('Reset demonstration data','reset','danger','','refresh')}</section><section class="panel pad"><h2>Demonstration views</h2><p>The staff selector changes the viewpoint and the “My referrals” filter. All views can edit the synthetic records. This is not production authentication or access control.</p></section></div></div>`;}
function guide(){return `<div class="page-head"><div><div class="eyebrow">GUIDANCE & RESEARCH</div><h1 tabindex="-1">Using Recovery Bridge</h1><p>A focused tool for recovery support and discharge coordination.</p></div><a class="btn" href="research.html" target="_blank" rel="noopener">Full research & evaluation pack ${icon('arrow')}</a></div><div class="docs-layout">${notice('Research prototype','Use fictional scenarios only. All demonstration accounts can edit. Staff remain responsible for clinical decisions.')}<details open><summary>A quick walkthrough</summary><div><ol><li>From <strong>Referral register</strong>, open an ACTS referral or choose <strong>New ACTS referral</strong>.</li><li>Under <strong>Treatment journey</strong>, record each ACTS contact, assessment, treatment milestone and outcome. Switch between <strong>Summary view</strong> and <strong>Detailed view</strong>.</li><li>Record goals, preferences, support decisions and barriers under <strong>Recovery support</strong>.</li><li>Under <strong>Discharge actions</strong>, add optional inpatient site, ward and planned discharge context when relevant. Add individual actions or select relevant example checklist items. Assign owners and dates.</li><li>Record submission and responses under <strong>Onward support</strong>. Confirm follow-up only when the details are known.</li><li>Review <strong>Handover</strong>, edit the preview and save, print or export it.</li></ol><p>Forms save when you select their Save button. Cancel closes a form without changing its record. Confirmation messages report successful browser saves.</p></div></details><details><summary>What the counts mean</summary><div><ul class="plain"><li><strong>ACTS referrals:</strong> journeys matching your filters. Open journeys include assessment, active treatment and follow-up. Select All journeys to include closed records.</li><li><strong>Outstanding:</strong> actions marked Not recorded, Pending or In progress.</li><li><strong>Overdue:</strong> outstanding actions with a due date earlier than the demo date. Missing due dates are not classified as overdue.</li><li><strong>Unassigned:</strong> outstanding actions without a named owner.</li><li><strong>Awaiting response:</strong> referrals marked Submitted.</li><li><strong>Follow-up to confirm:</strong> arrangements marked Pending or Not recorded.</li></ul><p>Counts recalculate across the filtered ACTS referrals. A record with no referral or follow-up entries is missing information; it does not add a fabricated pending entry. Missing sections remain visible in the referral and handover.</p></div></details><details><summary>Status meanings and save behaviour</summary><div><p><strong>Not recorded</strong> means the information is missing. <strong>Pending</strong> means the need or next step is known but unfinished. <strong>Completed</strong> means that action was recorded as done. <strong>Declined</strong> is a recorded choice. <strong>Not applicable</strong> means the item is not relevant to this plan.</p><p>Support discussion, offer, the person’s decision and arrangement are separate fields. Referral acceptance is separate from confirmed follow-up. Submitted and accepted referrals require a recorded date and reviewed consent status.</p><p>Completed actions receive a real completion timestamp in London time. Reopening clears the current completion timestamp. Handover drafts are refreshed from the record when the source changes.</p><p>Changes persist on this browser and device. Reset removes your local edits and restores the original dataset.</p></div></details><details><summary>Keyboard use</summary><div><p>Use Tab and Shift+Tab to move between controls, Enter or Space to activate buttons, and arrow keys to navigate referral section tabs. Home / End select the first / last tab. Dialogs use native modal behaviour; Escape closes them. Focus returns to the control that opened the form.</p><p>Browser-based keyboard, screen-reader, zoom and print checks remain part of the planned evaluation; no WCAG conformance claim is made.</p></div></details><details><summary>Research materials and limitations</summary><div><p>The separate research pack includes the requirement mapping, behavioural design rationale, evaluation guide, setup instructions, data model and verification limits.</p><p>No clinical-system access, clinical recommendation engine, real service directory, production authentication or clinical effectiveness evidence is included.</p><a href="research.html" target="_blank" rel="noopener">Open the full research & evaluation pack</a></div></details></div>`;}
function openDialog(title,body,onSubmit,subtitle='',saveLabel='Save changes'){
 opener=document.activeElement;dialog.innerHTML=`<form id="dialog-form"><div class="dialog-header"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button type="button" class="close-btn" data-close aria-label="Close form">${icon('close')}</button></div><div class="dialog-body">${body}<p class="form-error" id="dialog-error" role="alert" tabindex="-1"></p></div><div class="dialog-footer"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">${saveLabel}</button></div></form>`;
 dialog.querySelector('form').addEventListener('submit',event=>{event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form));const error=onSubmit(data,form);if(error){const el=document.getElementById('dialog-error');el.textContent=error;el.focus();return;}dialog.close();render();});dialog.showModal();dialog.querySelector('input:not([disabled]),select,textarea')?.focus();
}
dialog.addEventListener('click',event=>{if(event.target.closest('[data-close]'))dialog.close()});
dialog.addEventListener('close',()=>{if(opener?.isConnected)opener.focus();else if(!focusMatch(opener))document.querySelector('main h1')?.focus();});
function editor(kind,id='',extra=''){
 const e=current();if(kind==='new-acts-referral'||kind==='edit-acts-referral'){
 const record=kind==='new-acts-referral'?newReferral(''):e;
 if(kind==='new-acts-referral')record.id='ACTS-DEMO-'+String(Math.max(0,...state.referrals.map(x=>Number(x.id.match(/(\d+)$/)?.[1])||0))+1).padStart(3,'0');
 openDialog(kind==='new-acts-referral'?'New fictional ACTS referral':'Edit ACTS referral details',`<div class="form-grid">${field('Fictional patient / scenario name','alias',record.alias,'text','required maxlength="50" data-full','Use fictional names only.')}${field('Referral received date','receivedDate',record.receivedDate,'date')}${field('Received time (optional)','receivedTime',record.receivedTime,'time')}${select('Referral route','route',record.route,[['','Not recorded'],'Ward team','Alcohol liaison','Emergency department','Self referral','Other'])}${select('ACTS journey status','journeyStatus',record.journeyStatus,JOURNEY_STATUSES)}${field('Reason for referral','reasonForReferral',record.reasonForReferral,'textarea','maxlength="800" data-full')}${ownerSelect('practitioner',record.practitioner,'Assigned ACTS practitioner')}</div>`,formData=>{const data=Object.fromEntries(['alias','receivedDate','receivedTime','route','journeyStatus','reasonForReferral','practitioner'].map(k=>[k,formData[k]??record[k]]));const error=validateACTSReferral({...record,...data},state.today);if(error)return error;if(kind==='new-acts-referral'){const next=structuredClone(state);next.referrals.push({...record,...data,alias:data.alias.trim()});if(!persist(next,'Fictional ACTS referral created.'))return 'Referral could not be saved.';page='referral';referralId=record.id;tab='journey';}else if(!updateReferral(x=>Object.assign(x,data,{alias:data.alias.trim()}),'ACTS referral details saved.'))return 'Changes could not be saved.';},'Synthetic data only. Closing a journey does not complete its outstanding actions.',kind==='new-acts-referral'?'Create referral':'Save changes');return;
 }
 if(kind==='inpatient-context'){
 openDialog('Inpatient & discharge context',`<div class="form-grid">${select('Site','site',e.site,[['','Not recorded'],'Poole','Bournemouth'])}${field('Ward','ward',e.ward,'text','maxlength="60"','Use a fictional ward only.')}${field('Planned discharge date','discharge',e.discharge,'date')}</div>`,data=>{if(!updateReferral(x=>Object.assign(x,{site:data.site,ward:data.ward.trim(),discharge:data.discharge}),'Inpatient and discharge context saved.'))return 'Changes could not be saved.';},'Optional information for inpatient work and discharge planning. Complete later when relevant.');return;
 }
 if(kind==='event'){
 const v=e.events.find(v=>v.id===id)||{id:uid('event'),type:'Review',title:'',date:state.today,time:'',status:'Completed',owner:e.practitioner,method:'',location:e.ward||'',duration:'',auditScore:'',notes:'',outcome:'',nextAction:'',recordedAt:null,updatedAt:null};
 openDialog(id?'Edit treatment event':'Add treatment event',`<div class="form-grid">${select('Event type','type',v.type,EVENT_TYPES)}${select('Event status','status',v.status,EVENT_STATUSES)}${field('Short event title','title',v.title,'text','required maxlength="180" data-full')}${field('Event / planned date','date',v.date,'date')}${field('Event time (optional)','time',v.time,'time')}${ownerSelect('owner',v.owner)}${select('Contact method','method',v.method,[['','Not recorded'],'In person','Telephone','Video','Written communication','Other'])}${field('Location (optional)','location',v.location,'text','maxlength="100"')}${field('Contact duration in minutes (optional)','duration',v.duration,'number','min="0" max="720" step="1"')}${field('Recorded AUDIT score (optional)','auditScore',v.auditScore,'number','min="0" max="40" step="1"','Copy an assessed score if relevant; no interpretation is generated.')}${field('Notes / individual context','notes',v.notes,'textarea','maxlength="1600" data-full')}${field('Outcome','outcome',v.outcome,'textarea','maxlength="1000" data-full')}${field('Next action','nextAction',v.nextAction,'text','maxlength="500" data-full')}</div>`,data=>{const error=validateEvent(data,e,state.today);if(error)return error;const now=new Date().toISOString();if(!updateReferral(x=>upsert(x.events,{...v,...data,title:data.title.trim(),recordedAt:v.recordedAt||now,updatedAt:now}),'Treatment event saved.'))return 'Event could not be saved.';},'Record what happened or what is planned. Event dates are separate from the time this record is saved.');return;
 }
 if(kind==='recovery-context'){
 openDialog('Preferences, resources & review',`<div class="form-grid">${field('Preferences expressed by the person','preferences',e.preferences,'textarea','maxlength="800" data-full')}${field('Information or resources provided','resources',e.resources,'textarea','maxlength="800" data-full')}${field('Planned review date','review',e.review,'date')}${select('Practical barriers reviewed','barrierReview',e.barrierReview,['Not recorded','Reviewed','Not applicable'])}</div>`,data=>{if(data.barrierReview==='Not applicable'&&e.barriers.some(b=>!['Resolved','Not applicable'].includes(b.status)))return 'This referral has unresolved barriers. Resolve or review those records before marking the section not applicable.';if(!updateReferral(x=>Object.assign(x,data),'Recovery context saved.'))return 'Changes could not be saved.';});return;
 }
 if(kind==='goal'){
 const g=e.goals.find(g=>g.id===id)||{id:uid('goal'),text:''};openDialog(id?'Edit recovery goal':'Record a recovery goal',field('Goal expressed by the person','text',g.text,'textarea','required maxlength="600"'),data=>{if(!data.text.trim())return 'Record a brief recovery goal.';if(!updateReferral(x=>upsert(x.goals,{...g,text:data.text.trim()}),'Recovery goal saved.'))return 'Changes could not be saved.';},'Use the person’s own priorities and non-stigmatising language.');return;
 }
 if(kind==='support'){
 const s=e.supports.find(s=>s.id===id)||{id:uid('support'),option:'',discussed:'Not recorded',offered:'Not recorded',decision:'Not recorded',arrangement:'Not recorded',notes:''};
 openDialog(id?'Edit recovery support':'Add recovery support',`<div class="form-grid">${field('Support option','option',s.option,'text','required maxlength="160" data-full')}${select('Discussion','discussed',s.discussed,['Not recorded','Pending',['Completed','Discussed'],'Not applicable'])}${select('Offer','offered',s.offered,['Not recorded','Pending',['Completed','Offered'],'Not applicable'])}${select('Person’s decision','decision',s.decision,['Not recorded','Pending','Accepted','Declined','Not applicable'])}${select('Arrangement','arrangement',s.arrangement,['Not recorded','Pending',['Completed','Arranged'],'Not applicable'])}${field('Individual context / what was agreed','notes',s.notes,'textarea','maxlength="800" data-full')}</div>`,data=>{if(data.arrangement==='Completed'&&data.decision!=='Accepted')return 'Record an accepted decision before marking the support arrangement completed.';if(!updateReferral(x=>upsert(x.supports,{...s,...data}),'Support record saved.'))return 'Changes could not be saved.';},'Record each stage independently. An offer is not an accepted or arranged service.');return;
 }
 if(kind==='barrier'){
 const b=e.barriers.find(b=>b.id===id)||{id:uid('barrier'),type:'Housing',context:'',status:'Open',action:''};openDialog(id?'Edit practical barrier':'Add a practical barrier',`<div class="form-grid">${select('Barrier type','type',b.type,['Housing','Transport','Communication','Access to services','Other'])}${select('Status','status',b.status,['Not recorded','Open','Action agreed','Resolved','Not applicable'])}${field('Relevant individual context','context',b.context,'textarea','maxlength="700" data-full')}${field('Agreed action to address the barrier','action',b.action,'textarea','maxlength="700" data-full')}</div>`,data=>{if(data.status==='Action agreed'&&!data.action.trim())return 'Record the agreed action or choose another barrier status.';if(!updateReferral(x=>{upsert(x.barriers,{...b,...data});x.barrierReview='Reviewed';},'Practical barrier saved.'))return 'Changes could not be saved.';},'Add only barriers relevant to this fictional plan.');return;
 }
 if(kind==='action'){
 const a=e.actions.find(a=>a.id===id)||{id:uid('action'),description:'',owner:e.practitioner,due:e.discharge,status:'Pending',notes:'',why:'',completedAt:null};
 openDialog(id?'Edit discharge action':'Add a discharge action',`<div class="form-grid">${field('Action description','description',a.description,'text','required maxlength="220" data-full')}${ownerSelect('owner',a.owner,'Action owner')}${field('Due date','due',a.due,'date')}${select('Status','status',a.status,ACTION_STATUSES)}${field('Notes (optional)','notes',a.notes,'textarea','maxlength="800" data-full')}</div>`,data=>{if(!data.description.trim())return 'Enter a brief action description.';if(!updateReferral(x=>upsert(x.actions,changeActionStatus({...a,...data,description:data.description.trim()},data.status)),'Discharge action saved.'))return 'Changes could not be saved.';},'Unassigned owners and missing dates remain visible for review.');return;
 }
 if(kind==='referral'){
 const r=e.onwardReferrals.find(r=>r.id===id)||{id:uid('referral'),service:extra||'',purpose:'',consent:'Not recorded',date:'',owner:e.practitioner,status:'Preparation',outcome:'',next:''};
 openDialog(id?'Edit onward referral':'Record an onward referral',`<datalist id="services">${DIRECTORY.map(s=>`<option value="${esc(s.name)}"></option>`).join('')}</datalist><div class="form-grid">${field('Service / organisation','service',r.service,'text','required maxlength="160" list="services" data-full')}${field('Purpose','purpose',r.purpose,'text','maxlength="500" data-full')}${select('Consent status','consent',r.consent,['Not recorded','Pending','Agreed','Declined','Not applicable'])}${select('Referral status','status',r.status,REFERRAL_STATUSES)}${field('Referral date','date',r.date,'date')}${ownerSelect('owner',r.owner)}${field('Response / outcome','outcome',r.outcome,'textarea','maxlength="800" data-full')}${field('Next action','next',r.next,'text','maxlength="500" data-full')}</div>`,data=>{const error=validateReferral(data);if(error)return error;if(!updateReferral(x=>upsert(x.onwardReferrals,{...r,...data}),'Referral record saved.'))return 'Changes could not be saved.';},'Record only. No referral is sent to any service.');return;
 }
 if(kind==='followup'){
 const linked=e.onwardReferrals.find(r=>r.id===extra),f=e.followups.find(f=>f.id===id)||{id:uid('follow'),service:linked?.service||'',onwardReferralId:linked?.id||'',date:'',time:'',method:'',details:'',owner:linked?.owner||e.practitioner,status:'Pending',next:''};
 openDialog(id?'Edit follow-up':'Record follow-up arrangements',`<div class="form-grid">${field('Service / organisation','service',f.service,'text','required maxlength="160" data-full')}${select('Linked referral (optional)','onwardReferralId',f.onwardReferralId,[['','No linked referral'],...e.onwardReferrals.map(r=>[r.id,r.service])])}${select('Status','status',f.status,FOLLOW_STATUSES)}${field('Date','date',f.date,'date')}${field('Time (optional)','time',f.time,'time')}${select('Contact method','method',f.method,[['','Not recorded'],'In person','Telephone','Video','Written communication','Other'])}${ownerSelect('owner',f.owner)}${field('Appointment / contact details','details',f.details,'textarea','maxlength="800" data-full')}${field('Next action','next',f.next,'text','maxlength="500" data-full')}</div>`,data=>{const error=validateFollow(data);if(error)return error;if(!updateReferral(x=>upsert(x.followups,{...f,...data}),'Follow-up record saved.'))return 'Changes could not be saved.';},'Confirmed follow-up needs a date, contact method, details and responsible practitioner.');return;
 }
}
function upsert(arr,item){const i=arr.findIndex(x=>x.id===item.id);if(i<0)arr.push(item);else arr[i]=item;}
function checklist(){const e=current();openDialog('Choose relevant checklist actions',`<p class="muted small">These are configurable planning prompts. Review relevance and ownership before adding them.</p>${state.templates.map(t=>{const exists=e.actions.some(a=>a.description===t.description);return `<label class="check-option"><input type="checkbox" name="template" value="${esc(t.id)}" ${exists?'disabled':''}><span><strong>${esc(t.description)} ${exists?'· already in plan':''}</strong><small>${esc(t.why)}</small></span></label>`}).join('')}<div class="form-grid" style="margin-top:20px">${ownerSelect('owner',e.practitioner,'Initial action owner')}${field('Initial due date','due',e.discharge,'date')}</div>`,(data,form)=>{const ids=new FormData(form).getAll('template');if(!ids.length)return 'Select at least one relevant action.';if(!updateReferral(x=>{for(const t of state.templates.filter(t=>ids.includes(t.id))){x.actions.push({id:uid('action'),description:t.description,why:t.why,owner:data.owner,due:data.due,status:'Pending',notes:'',completedAt:null});}},'Selected checklist actions added.'))return 'Changes could not be saved.';},'Checklist completion is not clinical discharge clearance.','Add selected actions');}
function directoryReferral(service){openDialog('Choose a fictional ACTS referral',select('ACTS referral','acts-referral',referralId||'', [['','Choose an ACTS referral'],...state.referrals.map(e=>[e.id,e.alias+' · '+e.id])],'required'),data=>{page='referral';referralId=data['acts-referral'];tab='referrals';setTimeout(()=>editor('referral','',service),50);},'The service details will be copied into a new referral form.','Continue');}
function summarySave(show=true){const e=current(),text=document.getElementById('summary-content').value;if(!text.trim()){flash('The summary cannot be empty. Refresh it from the record or enter an edited draft.');return false;}const ok=updateReferral(x=>{x.handoverDraft=text;x.handoverSource=summary(x,state.staff);x.handoverSavedAt=new Date().toISOString();},show?'Edited handover draft saved.':'');if(ok){const el=document.getElementById('summary-content');el.dataset.initial=text;document.getElementById('summary-save').textContent='Edited draft saved '+stamp(current().handoverSavedAt)+'.';}return ok;}
function download(name,text,mime='text/plain'){const blob=new Blob([text],{type:mime+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
app.addEventListener('click',event=>{const el=event.target.closest('[data-act]');if(!el)return;const act=el.dataset.act,id=el.dataset.id;
 if(act==='nav'){navigate(el.dataset.page);return;}if(act==='open'){navigate('referral',id,el.dataset.tab||'journey');return;}if(act==='tab'){if(!safeLeave())return;tab=el.dataset.tab;render();document.getElementById('tab-'+tab)?.focus();return;}
 if(['new-acts-referral','edit-acts-referral','inpatient-context','event','goal','support','barrier','recovery-context','action','referral','followup'].includes(act)){editor(act,id,el.dataset.ref||'');return;}if(act==='checklist'){checklist();return;}
 if(act==='timeline-view'){timelineView=el.dataset.view;render();return;}
 if(act==='metric'){filters.attention=el.dataset.key==='referrals'?'':filters.attention===el.dataset.key?'':el.dataset.key;render();return;}if(act==='my-referrals'){filters.worker=person().id;render();return;}if(act==='clear-filters'){filters={search:'',site:'',ward:'',worker:'',from:'',to:'',status:'',attention:'',journey:'Open'};render();return;}
 if(act==='complete-action'||act==='reopen-action'){updateReferral(e=>{const a=e.actions.find(a=>a.id===id);upsert(e.actions,changeActionStatus(a,act==='complete-action'?'Completed':'Pending'));},act==='complete-action'?'Action marked completed.':'Action reopened; completion timestamp cleared.');render();return;}
 if(act==='directory-referral'){directoryReferral(el.dataset.service);return;}
 if(act==='save-summary'){summarySave();return;}if(act==='refresh-summary'){if(!confirm('Replace the preview and any saved draft with a fresh summary from the current record?'))return;updateReferral(e=>{e.handoverDraft=null;e.handoverSource=null;e.handoverSavedAt=null;},'Handover refreshed from the referral record.');render();return;}
 if(act==='print-summary'||act==='export-summary'){if(!summarySave(false))return;const text=document.getElementById('summary-content').value;if(act==='print-summary'){document.getElementById('print-area').textContent=text;window.print();}else{download(current().id+'-fictional-handover.txt',text);flash('Handover text exported.');}return;}
 if(act==='export-data'){download('recovery-bridge-synthetic-data.json',JSON.stringify(state,null,2),'application/json');flash('Synthetic dataset exported.');return;}
 if(act==='reset'){openDialog('Reset demonstration data?',`<p>This will remove local edits and restore the original six fictional scenarios, example checklist and reference date.</p><p>Export the synthetic dataset first if you want to retain a copy.</p>`,()=>{if(!persist(structuredClone(SEED),'Original demonstration dataset restored.',true))return 'Reset failed. Check browser storage availability.';filters={};page='overview';referralId=null;},'This applies only to this browser.','Reset demonstration data');return;}
 if(act==='add-template'){openDialog('Add checklist item',`<div class="form-grid">${field('Action description','description','','text','required maxlength="220" data-full')}${field('Why it matters','why','','text','maxlength="220" data-full')}</div>`,data=>{if(!data.description.trim())return 'Enter an action description.';const next=structuredClone(state);next.templates.push({id:uid('template'),description:data.description.trim(),why:data.why.trim()});if(!persist(next,'Checklist item added.'))return 'Item could not be saved.';});}
});
app.addEventListener('input',event=>{const el=event.target;if(el.dataset.timeline){timelineFilters[el.dataset.timeline]=el.value;render();document.getElementById(el.id)?.focus();return;}if(el.dataset.filter==='search'){const pos=el.selectionStart;filters.search=el.value;render();const replacement=document.getElementById('search');replacement.focus();replacement.setSelectionRange(pos,pos);}if(el.id==='summary-content')document.getElementById('summary-save').textContent=el.value===el.dataset.initial?'No unsaved edits.':'Unsaved preview edits — save before leaving.';});
app.addEventListener('change',event=>{const el=event.target;if(el.dataset.timeline){timelineFilters[el.dataset.timeline]=el.value;render();document.getElementById(el.id)?.focus();return;}if(el.dataset.filter&&el.dataset.filter!=='search'){const name=el.id;filters[el.dataset.filter]=el.value;render();document.getElementById(name)?.focus();}if(el.id==='demo-staff'){if(!safeLeave()){el.value=state.selectedStaff;return;}const next=structuredClone(state);next.selectedStaff=el.value;persist(next,'Demonstration view changed. All views can edit synthetic records.');render();}if(el.id==='action-filter'){actionFilter=el.value;render();document.getElementById('action-filter').focus();}});
app.addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));if(event.target.id==='date-form'){const next=structuredClone(state);next.today=data['demo-date'];persist(next,'Demonstration date updated.');render();}if(event.target.id==='templates-form'){const next=structuredClone(state);next.templates=state.templates.map((t,i)=>({...t,description:data['template-'+i].trim(),why:data['why-'+i].trim()}));if(next.templates.some(t=>!t.description)){document.getElementById('template-error').textContent='Each checklist item needs an action description.';return;}if(new Set(next.templates.map(t=>t.description)).size!==next.templates.length){document.getElementById('template-error').textContent='Use a unique description for each checklist item.';return;}persist(next,'Example checklist saved.');render();}});
app.addEventListener('keydown',event=>{const active=event.target.closest('[role="tab"]');if(!active||!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();if(!safeLeave())return;const keys=['journey','recovery','actions','referrals','handover'],i=keys.indexOf(tab);tab=event.key==='Home'?keys[0]:event.key==='End'?keys[4]:keys[(i+(event.key==='ArrowRight'?1:4))%5];render();document.getElementById('tab-'+tab)?.focus();});
render();
